/// java: public interface OptionAccess
///
/// An accessor to all options that are auto-generated by the config system. `&self` methods: an operation
/// scheduled here runs listeners that schedule again (`MasterTickBoxImpl.listener`).
pub trait OptionAccess: compat::DynAny {
    /// java: @Nullable Option<?> getOption(String fieldName); (`Option<?>` is `AnyOption`)
    ///
    /// The option of the field with this exact, case-sensitive name, or `None` if it has not been created yet (they
    /// are created in the order of the fields in the class).
    fn get_option(&self, field_name: &str) -> Option<Arc<dyn AnyOption>>;

    /// java: void scheduleOptionOperation(String fieldName, Consumer<Option<?>> optionConsumer);
    ///
    /// Runs the operation now if the option exists, otherwise once it is created.
    fn schedule_option_operation(&self, field_name: &str, option_consumer: Arc<dyn Fn(Arc<dyn AnyOption>)>);
}
